<?php require __DIR__.'/includes/bootstrap.php';require_permission('users.manage');require __DIR__.'/includes/layout.php';require __DIR__.'/includes/data.php';$create=($_GET['action']??'')==='create';if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$hash=password_hash($_POST['password'],PASSWORD_DEFAULT);$pdo->prepare('INSERT INTO users(role_id,branch_id,name,email,phone,password_hash,status,force_password_change) VALUES(?,?,?,?,?,?,"active",1)')->execute([(int)$_POST['role_id'],$_POST['branch_id']?:null,trim($_POST['name']),strtolower(trim($_POST['email'])),trim($_POST['phone']),$hash]);$id=(int)$pdo->lastInsertId();audit($pdo,'create','users',$id);flash('success','User account created. They must change their password after sign-in.');redirect('users.php');}render_header('Users','users');page_title('Users & Roles','ACCESS CONTROL','Manage secure accounts, role assignments and branch scope.',$create?'':'Add User',app_url('users.php?action=create'));if($create):$roles=options($pdo,'roles','name','1=1');$branches=options($pdo,'branches');?><article class="card form-card"><form method="post"><?=csrf_field()?><div class="form-grid"><label>Full Name<input name="name" required></label><label>Email<input type="email" name="email" required></label><label>Phone<input name="phone"></label><label>Temporary Password<input type="password" name="password" minlength="10" required></label><label>Role<select name="role_id"><?php foreach($roles as $x):?><option value="<?=$x['id']?>"><?=e($x['label'])?></option><?php endforeach;?></select></label><label>Branch Scope<select name="branch_id"><option value="">All branches</option><?php foreach($branches as $x):?><option value="<?=$x['id']?>"><?=e($x['label'])?></option><?php endforeach;?></select></label></div><div class="form-actions"><a class="btn" href="<?=app_url('users.php')?>">Cancel</a><button class="btn primary">Create Account</button></div></form></article><?php else:$rows=$pdo->query('SELECT u.*,r.name role,b.name branch FROM users u JOIN roles r ON r.id=u.role_id LEFT JOIN branches b ON b.id=u.branch_id WHERE u.deleted_at IS NULL ORDER BY u.id')->fetchAll();?><article class="card table-card"><div class="table-wrap"><table><thead><tr><th>User</th><th>Role</th><th>Branch</th><th>Phone</th><th>Last Login</th><th>Status</th></tr></thead><tbody><?php foreach($rows as $r):?><tr><td data-label="User"><b><?=e($r['name'])?></b><small style="display:block;color:var(--muted)"><?=e($r['email'])?></small></td><td data-label="Role"><?=e($r['role'])?></td><td data-label="Branch"><?=e($r['branch']??'All Branches')?></td><td data-label="Phone"><?=e($r['phone'])?></td><td data-label="Last Login"><?=$r['last_login_at']?date('d M Y H:i',strtotime($r['last_login_at'])):'Never'?></td><td data-label="Status"><span class="status"><?=e(ucfirst($r['status']))?></span></td></tr><?php endforeach;?></tbody></table></div></article><?php endif;render_footer('users');
